if [[ "$1" = "screenrecord" ]]; then

    ~/.android-toolkit/libs/adb shell mkdir /sdcard/tmp # Create temporary location on device to store video
    ~/.android-toolkit/libs/adb shell screenrecord /sdcard/tmp/tmp.mp4 & # Record
    PID=$(pgrep -f ~/.android-toolkit/libs/adb shell screenrecord /sdcard/tmp/tmp.mp4) # Get Process ID

    read -p "Recording...\n\nPress ENTER to stop." null

    kill "$PID"

fi

